using Microsoft.EntityFrameworkCore;
using Osynix.Ats.Data;
using Osynix.Ats.Domain;
namespace Osynix.Ats.Services;
public record RecruiterActionItem(RecruiterAction Action,string Candidate,string Client,string Position,string Reference,Guid? WorkspaceId,bool Agency,bool Mine,string AssignedTo="");
public class RecruiterActionService(IDbContextFactory<AtsDbContext> factory,Access access,RecruitmentUpdates updates){
 public static async Task<string?> Recipient(AtsDbContext db,HiringSubmission sub,Position p){
  var sender=await db.Users.FindAsync(sub.SubmittedBy);if(p.WorkspaceId is not Guid wid)return sender?.Status=="Active"?sender.Id:null;
  var w=await db.EmployerWorkspaces.FindAsync(wid);if(w is null||!await WorkspaceContext.OwnerActive(db,w.OwnerId))return null;
  async Task<bool> Eligible(AtsUser? u){if(u is null||u.Status!="Active"||!u.EmailConfirmed)return false;if(u.Id==w.OwnerId)return true;return await db.WorkspaceMemberships.AnyAsync(m=>m.WorkspaceId==wid&&m.UserId==u.Id&&m.Status=="Active")&&(p.AssignedRecruiter==u.UserName||await db.PositionRecruiterAssignments.AnyAsync(a=>a.PositionId==p.Id&&a.UserId==u.Id));}
  if(await Eligible(sender))return sender!.Id;var assigned=await db.Users.SingleOrDefaultAsync(u=>u.UserName==p.AssignedRecruiter);if(await Eligible(assigned))return assigned!.Id;return w.OwnerId;
 }
 public static async Task Capture(AtsDbContext db,HiringSubmission sub,Assessment app){var p=await db.Positions.SingleAsync(p=>p.Id==app.PositionId);var action=await db.RecruiterActions.SingleOrDefaultAsync(t=>t.AssessmentId==app.Id);if(action is null){action=new(){AssessmentId=app.Id};db.Add(action);}action.SubmissionId=sub.Id;action.RecipientId=await Recipient(db,sub,p);action.Type=sub.Feedback switch{"More Information Required"=>"Respond To Client","Request Interview"=>"Arrange Interview","Recommend Hire"=>"Finalize Hiring","Send Offer"=>"Send Offer",_=>"Review Feedback"};action.Title=sub.Feedback switch{"Shortlist"=>"Review Client Shortlist","Hold"=>"Review Held Profile","Reject"=>"Review Client Rejection","More Information Required"=>"Provide Requested Information","Request Interview"=>"Arrange Client Interview","Recommend Hire"=>"Confirm Hiring Outcome","Send Offer"=>"Prepare And Send Offer",_=>"Review Client Feedback"};action.Feedback=sub.Feedback;action.Remarks=sub.Remarks;action.FeedbackUtc=sub.FeedbackUtc??DateTime.UtcNow;action.Status="Open";action.CompletedUtc=null;}
 public static async Task Backfill(AtsDbContext db){
  var pending=await (from sub in db.HiringSubmissions join grant in db.HiringReviewGrants on sub.GrantId equals grant.Id join app in db.Assessments on sub.AssessmentId equals app.Id join position in db.Positions on app.PositionId equals position.Id where !sub.Revoked&&!grant.Revoked&&sub.FeedbackUtc!=null&&sub.Feedback!="Awaiting Feedback"&&app.State=="Saved"&&(position.Status=="Active"||position.Status=="On Hold")&&app.Stage!="Hired"&&app.Stage!="Offer Sent"&&!db.RecruiterActions.Any(t=>t.AssessmentId==app.Id) select new{sub,app}).ToListAsync();
  foreach(var row in pending.GroupBy(x=>x.app.Id).Select(g=>g.OrderByDescending(x=>x.sub.FeedbackUtc).First())){
   if(row.sub.Feedback=="Request Interview"&&(row.app.InterviewStatus=="Scheduled"||row.app.InterviewStatus=="Completed"))continue;
   if(row.sub.Feedback=="Request Interview"&&row.app.Stage=="Client Interview"){row.app.Stage="Interview Requested";row.app.ClientStatus="Interview Requested";}
   await Capture(db,row.sub,row.app);
  }
  await db.SaveChangesAsync();
 }
 public Task<List<RecruiterActionItem>> Inbox(bool team=false,bool allWork=false)=>LoadInbox(team,allWork,0,false);
 public Task<List<RecruiterActionItem>> Notifications(bool allWork=true)=>LoadInbox(false,allWork,0,true);
 async Task<List<RecruiterActionItem>> LoadInbox(bool team,bool allWork,int attempt,bool includeUpdates){var principal=await access.Require();var uid=await access.UserId();var active=await access.Context();List<Assessment> apps;
 await using var db=await factory.CreateDbContextAsync();
 if(allWork&&!principal.IsInRole("Admin")){var choices=await WorkspaceContext.Choices(db,principal);var own=choices.FirstOrDefault(c=>c.Owner);var ownId=own?.Id;var teams=choices.Where(c=>!c.Owner).Select(c=>c.Id).ToList();var username=(await db.Users.FindAsync(uid))!.UserName;var positions=await db.Positions.Where(p=>(ownId!=null&&p.WorkspaceId==ownId&&(!p.IsAgencyPosition||db.EmployerWorkspaces.Any(w=>w.Id==ownId&&w.AgencyEnabled)))||(p.WorkspaceId!=null&&teams.Contains(p.WorkspaceId.Value)&&(p.AssignedRecruiter==username||db.PositionRecruiterAssignments.Any(a=>a.PositionId==p.Id&&a.UserId==uid)))).Select(p=>p.Id).ToListAsync();apps=await db.Assessments.Include(a=>a.Position).AsNoTracking().Where(a=>a.State=="Saved"&&positions.Contains(a.PositionId)).ToListAsync();}
 else apps=(await new AtsService(factory,access).Assessments()).Where(a=>a.State=="Saved").ToList();
 var ids=apps.Select(a=>a.Id).ToList();var tasks=await db.RecruiterActions.Where(t=>ids.Contains(t.AssessmentId)&&t.Status=="Open").OrderByDescending(t=>t.FeedbackUtc).ToListAsync();var result=new List<RecruiterActionItem>();foreach(var task in tasks){var app=apps.Single(a=>a.Id==task.AssessmentId);var sub=await db.HiringSubmissions.FindAsync(task.SubmissionId);var grant=sub is null?null:await db.HiringReviewGrants.FindAsync(sub.GrantId);if(sub is null||sub.Revoked||grant?.Revoked==true){task.Status="Cancelled";task.CompletedUtc=DateTime.UtcNow;continue;}var recipient=await Recipient(db,sub,app.Position!);if(task.RecipientId!=recipient){task.RecipientId=recipient;AtsService.Audit(db,uid,"Client task reassigned",task.Id.ToString(),recipient??"Admin Attention Required",app.CandidateId,app.Id);}if(((app.Stage is "Hired" or "Rejected" or "Offer Sent")&&task.Type!="Review Feedback")||(task.Type=="Arrange Interview"&&(app.InterviewStatus is "Scheduled" or "Completed"))){task.Status="Completed";task.CompletedUtc=DateTime.UtcNow;continue;}if(task.RecipientId==uid||team&&((active?.Owner==true&&active.Id==app.Position!.WorkspaceId)||principal.IsInRole("Admin")))result.Add(new(task,app.CandidateName,app.Position!.Client,app.Position.Title,app.Position.Reference,app.Position.WorkspaceId,app.Position.IsAgencyPosition,task.RecipientId==uid,(await db.Users.FindAsync(task.RecipientId??"")) is AtsUser assignee?(string.IsNullOrWhiteSpace(assignee.FullName)?assignee.UserName??"Team Member":assignee.FullName):"Unassigned"));}try{await db.SaveChangesAsync();}catch(DbUpdateConcurrencyException)when(attempt<2){return await LoadInbox(team,allWork,attempt+1,includeUpdates);}return includeUpdates?result:result.Where(t=>t.Action.Type!="Review Feedback").ToList();}
 public async Task Acknowledge(Guid id,Guid revision,bool allWork=false){var items=await LoadInbox(true,allWork,0,true);var item=items.SingleOrDefault(t=>t.Action.Id==id)??throw new UnauthorizedAccessException("This Task Is Not Available In Your Workspace.");if(item.Action.Type!="Review Feedback")throw new InvalidOperationException("Respond To The Client Or Update The Interview In The Application Before Completing This Task.");await using var db=await factory.CreateDbContextAsync();var action=await db.RecruiterActions.SingleAsync(t=>t.Id==id);if(action.Revision!=revision)throw new DbUpdateConcurrencyException("This Task Changed. Reload Before Acknowledging It.");action.Status="Completed";action.CompletedUtc=DateTime.UtcNow;AtsService.Audit(db,await access.UserId(),"Client feedback acknowledged",id.ToString(),"",null,action.AssessmentId);await db.SaveChangesAsync();updates.Publish();}
}
